import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"子夏易传 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"子夏易传 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/zixia/020.md","filePath":"zh/classics/zixia/020.md"}'),i={name:"zh/classics/zixia/020.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><p>卦辞：蠱，元亨，利涉大川，先甲三日，後甲三日。</p><p>彖曰：蠱，剛上而柔下，巽而止，蠱。蠱，元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。</p><p>子夏：蠱，文皿蟲也。風過山也。時之蠱，而事繫之，不可以無制，作也。剛升而上，柔來而下，剛柔兩得其情，大通而柔伏也。巽而上，無違迕也。故可以造治制作，而無難也。古之為治者，以質文相變也。弊而更之，之謂也。以質治者，寛而任人，親而不尊，其弊也。野而不近，縱而難禁，故因其弊而反之以文。以文治者，檢而有度，尊而不親，其弊也。煩而多賊，近而無實，因其弊而更之以質。質文更代，終則有始。如寒暑之謝也。甲者，制事之首也。夫立制者，必先究前弊之由，察其中，要其終。故先三日，以原之，然後更之，今及其先，乃及其後。後甲三日之正，故能合其時，而當於人心也。殷因於夏，周因於殷，故為之改命，創制天下法也。</p><p>象曰：山下有風，蠱。君子以振民育德。</p><p>子夏：山下有風，時蠱而制事也。君子將以振民，先有其德然後制作也。</p><p>初六，幹父之蠱，有子考，无咎，厲終吉。</p><p>象曰：幹父之蠱，意承考也。</p><p>子夏：有為者，臣子之職也。受命者，承其意而損益從時，而後蠱，可幹也。柔始受命，能終其事。承父之後也，可謂有子矣。考何咎乎。臨事而專，故曰厲也。終成其志，得无咎也。有事之道也。</p><p>九二，幹母之蠱，不可貞。</p><p>象曰：幹母之蠱，得中道也。</p><p>子夏：幹内應柔，承母之事也。不可以自正，非所越也。乃得中道矣。事有順而後成者，此之謂也。</p><p>九三，幹父之蠱，小有悔，无大咎。</p><p>象曰：幹父之蠱，終无咎也。</p><p>子夏：以剛得位，幹其事而專其任也。專之故，小悔，終成其志，故无咎也。</p><p>六四，裕父之蠱，往見吝。</p><p>象曰：裕父之蠱，往未得也。</p><p>子夏：柔之位，而以柔處之，不能敏於事也。是寛其事而无成也。復命得乎，往見吝矣，終无功也。</p><p>六五，幹父之蠱，用譽。</p><p>象曰：幹父用譽，承以德也。</p><p>子夏：柔非能幹蠱也。事必有主之者矣，用德而不勞於力，五之謂歟。居得中正，衆之所荷，用譽之謂也。</p><p>上九，不事王侯，髙尚其事。</p><p>象曰：不事王侯，志可則也。</p><p>子夏：剛上者，主之尚也，令之源也。終其事而不享其利，以髙尚為事，可企而則也。不事王侯，可以尚之也。</p>',24)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
